/* ===== Русский язык — по учебнику Ладыженской, Баранова и др. для 5–6 классов ===== */
/* ===== Орфография Ани (решение методсовета 21.11): не «одна из двух букв» (угадывается в половине случаев), а 3–4 варианта:
   «вставь в два слова по порядку» (4 сочетания), «в каком слове пропущена такая буква» (4 слова) и «Почему так пишется?» (выбор правила).
   Слово: [с пропуском, верно, типичная ошибка, номер правила (-1 — слово на запоминание), правила, которые к слову не предлагать (100+k — ловушки), проверочное слово для пояснения].
   o.same — правила с той же буквой ясно различаются и годятся как неверные варианты; o.traps — неверные «правила» (типичные заблуждения); o.wq — вопрос «в каком слове». */
function ORF(items, rules, o){ o = o || {}; const traps = o.traps || [];
  const I = items.map(x => ({ gap: x[0], a: x[1], w: x[2], ri: x[3], x: x[4] || [], why: x[5] || '' }));
  const full = it => it.gap.indexOf('(не)') >= 0 ? it.gap.replace('(не)', it.a === 'слитно' ? '<b>не</b>' : '<b>не</b> ') : /^без /.test(it.a) ? it.gap.replace('_', '') : it.gap.replace('_', '<b>' + it.a + '</b>');
  const why = it => (rules[it.ri] || 'это написание надо запомнить') + (it.why ? ` (${it.why})` : '');
  const rl = j => { const it = I.find(z => z.ri === j); return it ? it.a : ''; };
  const pair = r => { const [p, q] = r.sample(I, 2);
    return C(`Вставь пропущенное по порядку:<br>1) ${p.gap}<br>2) ${q.gap}`, `${p.a}, ${q.a}`, [`${p.a}, ${q.w}`, `${p.w}, ${q.a}`, `${p.w}, ${q.w}`], `1) ${full(p)} — ${why(p)}.<br>2) ${full(q)} — ${why(q)}.`); };
  const which = r => { const ok = I.filter(it => I.filter(z => z.w === it.a).length >= 3); if (!ok.length) return pair(r);
    const X = r.pick(ok).a, c = r.pick(I.filter(z => z.a === X)), ds = r.sample(I.filter(z => z.w === X), 3);
    return C(o.wq ? o.wq(X) : `В каком слове пропущена буква <b>${X}</b>?`, c.gap, ds.map(z => z.gap), `${full(c)} — ${why(c)}.<br>В остальных: ${ds.map(full).join(', ')}.`); };
  const because = r => { const it = r.pick(I.filter(z => z.ri >= 0)), right = rules[it.ri];
    const pool = rules.map((t, j) => j).filter(j => j !== it.ri && it.x.indexOf(j) < 0 && (o.same || rl(j) !== it.a)).map(j => rules[j])
      .concat(traps.filter((t, k) => it.x.indexOf(100 + k) < 0)).filter(t => t !== right);
    if (pool.length < 2) return pair(r);
    const w = full(it).replace(/ \([^)]*\)$/, ''); /* подсказку в скобках («под ударением», «каков?») здесь не показываем — она называет правило */
    return C(/^без /.test(it.a) ? `Почему в слове «${w}» ${it.a.replace('без ', 'не пишем ')}?` : `Почему так пишется: «${w}»?`, right, r.sample(pool, 3), `${w} — ${why(it)}.`); };
  const gs = [pair, which, because].concat(o.extra ? [o.extra] : []);
  return r => r.pick(gs)(r); }

